from pathlib import Path

p = Path('public/erp_financeiro_completo.html')
s = p.read_text()
start = s.index('function clientReportFor(key)')
end = s.index('function selectedRows()', start)
block = r'''function reportGroupsFromRows(rows=[]){const clients=new Map();for(const r of rows){const ck=customerKey(r);if(!clients.has(ck))clients.set(ck,{key:ck,name:r.customerName||'Consumidor',cpf:r.customerCpf||'',phone:r.customerPhone||'',email:r.customerEmail||'',purchases:new Map()});const c=clients.get(ck);if(!c.purchases.has(r.purchaseKey))c.purchases.set(r.purchaseKey,{key:r.purchaseKey,ref:r.purchaseRef,sourceType:r.sourceType,orderId:r.orderId,rows:[]});c.purchases.get(r.purchaseKey).rows.push(r)}return[...clients.values()].map(c=>({...c,purchases:[...c.purchases.values()]}))}
async function reportHistoricalInfo(p){if(!String(p.key||'').startsWith('sige:'))return{installments:0,items:[]};const sid=String(p.key).slice(5);try{const d=await api('/erp/migracao/sige/compras/'+encodeURIComponent(sid)),sale=d.purchase||{},live=sale?.metadata?.sigeLive||{},payments=live.payments||[],items=(live.items?.length?live.items:sale.items)||[];return{installments:Number(live.numberOfInstallments||payments[0]?.installments||sale.numberOfInstallments||0),items:items.map(x=>String(x.description||x.name||x.productName||'').trim()).filter(Boolean)}}catch{return{installments:0,items:[]}}}
async function clientReportFor(key){
 const base=collectionGroups().find(x=>x.key===key);if(!base)return null;
 let sourceRows=collections;
 try{const q=base.cpf||base.name,p=new URLSearchParams({direction:'receivable',q});const d=await api('/erp/financeiro/completo?'+p);const all=prepareCollections(d.entries||[]).filter(r=>customerKey(r)===key);if(all.length)sourceRows=all}catch{}
 const c=reportGroupsFromRows(sourceRows).find(x=>x.key===key)||base;
 const now=today(),sections=[];let totalPrincipal=0,totalFine=0,totalInterest=0,totalUpdated=0,totalOpen=0,totalOverdue=0;
 for(const p of c.purchases){
  const openRows=p.rows.filter(r=>['pendente','parcial'].includes(r.status)&&Number(r.remaining||0)>0.009).sort((a,b)=>new Date(a.dueAt||0)-new Date(b.dueAt||0));
  if(!openRows.length)continue;
  const hist=await reportHistoricalInfo(p),declared=Math.max(0,...p.rows.map(r=>Number(r.installments||0))),maxNumber=Math.max(0,...p.rows.map(r=>Number(r.number||0))),originalInstallments=Math.max(Number(hist.installments||0),declared,maxNumber,p.rows.length);
  let principal=0,fine=0,interest=0,updated=0,overdueCount=0;const rows=[];
  for(const r of openRows){const pval=Math.max(0,Number(r.remaining||0)),calc=calculateLateCharges(r,pval,now,false),isOver=calc.days>0;principal+=pval;fine+=Number(calc.fine||0);interest+=Number(calc.interest||0);updated+=Number(calc.total||pval);if(isOver)overdueCount++;rows.push({parcela:(r.number||0)+'/'+(originalInstallments||r.installments||0),vencimento:date(r.dueAt),principal:pval,multa:Number(calc.fine||0),juros:Number(calc.interest||0),atualizado:Number(calc.total||pval),situacao:isOver?'VENCIDA':'EM ABERTO'});}
  totalPrincipal+=principal;totalFine+=fine;totalInterest+=interest;totalUpdated+=updated;totalOpen+=openRows.length;totalOverdue+=overdueCount;sections.push({title:'COMPRA '+(sections.length+1)+' — '+(p.ref||'Compra'),rows,principal,fine,interest,updated,originalInstallments,items:hist.items});
 }
 if(!sections.length)return{client:c,text:'',html:''};
 const plain=[];plain.push('ARIANA MÓVEIS','RELATÓRIO DE CONTAS A RECEBER','Cliente: '+c.name,'Atualizado em: '+new Date().toLocaleString('pt-BR'),'');for(const sec of sections){plain.push(sec.title);if(sec.items.length)plain.push('Produto(s): '+sec.items.join(' / '));plain.push('Parcelamento original: '+sec.originalInstallments+' parcela(s)','Parcela | Vencimento | Principal | Multa | Juros | Atualizado | Situação');for(const r of sec.rows)plain.push([r.parcela,r.vencimento,money(r.principal),money(r.multa),money(r.juros),money(r.atualizado),r.situacao].join(' | '));plain.push('Subtotal principal: '+money(sec.principal),'Multa: '+money(sec.fine),'Juros: '+money(sec.interest),'Subtotal atualizado: '+money(sec.updated),'');}plain.push('RESUMO GERAL','Parcelas em aberto: '+totalOpen,'Parcelas vencidas: '+totalOverdue,'Principal em aberto: '+money(totalPrincipal),'Multa: '+money(totalFine),'Juros: '+money(totalInterest),'TOTAL ATUALIZADO: '+money(totalUpdated));
 const cell='padding:7px 8px;border:1px solid #d6dee9;vertical-align:middle;';let html='<div style="font-family:Arial,sans-serif;color:#172033;font-size:11pt;line-height:1.35">';
 sections.forEach((sec,i)=>{html+='<section class="report-page" style="'+(i?'page-break-before:always;break-before:page;':'')+'min-height:950px;padding:4px 0 24px"><div style="font-size:15pt;font-weight:700">ARIANA MÓVEIS</div><div style="font-size:13pt;font-weight:700;margin-bottom:14px">RELATÓRIO DE CONTAS A RECEBER</div><div><b>Cliente:</b> '+esc(c.name)+'</div>'+(c.cpf?'<div><b>CPF/CNPJ:</b> '+esc(c.cpf)+'</div>':'')+'<div><b>Atualizado em:</b> '+esc(new Date().toLocaleString('pt-BR'))+'</div><div style="margin-top:20px;font-size:13pt;font-weight:700">'+esc(sec.title)+'</div>'+(sec.items.length?'<div style="margin:5px 0 2px"><b>Produto(s):</b> '+sec.items.map(esc).join(' / ')+'</div>':'')+'<div style="margin:2px 0 8px"><b>Parcelamento original:</b> '+sec.originalInstallments+' parcela(s)</div><table style="border-collapse:collapse;width:100%;table-layout:fixed;margin-top:6px;font-family:Arial,sans-serif;font-size:10pt"><colgroup><col style="width:10%"><col style="width:15%"><col style="width:15%"><col style="width:13%"><col style="width:13%"><col style="width:17%"><col style="width:17%"></colgroup><thead><tr><th style="'+cell+'text-align:center">Parcela</th><th style="'+cell+'text-align:center">Vencimento</th><th style="'+cell+'text-align:right">Principal</th><th style="'+cell+'text-align:right">Multa</th><th style="'+cell+'text-align:right">Juros</th><th style="'+cell+'text-align:right">Atualizado</th><th style="'+cell+'text-align:center">Situação</th></tr></thead><tbody>';for(const r of sec.rows)html+='<tr><td style="'+cell+'text-align:center">'+esc(r.parcela)+'</td><td style="'+cell+'text-align:center">'+esc(r.vencimento)+'</td><td style="'+cell+'text-align:right">'+money(r.principal)+'</td><td style="'+cell+'text-align:right">'+money(r.multa)+'</td><td style="'+cell+'text-align:right">'+money(r.juros)+'</td><td style="'+cell+'text-align:right;font-weight:700">'+money(r.atualizado)+'</td><td style="'+cell+'text-align:center">'+r.situacao+'</td></tr>';html+='</tbody></table><div style="margin-top:10px;border-top:1px solid #cbd5e1;padding-top:8px"><b>Subtotal principal:</b> '+money(sec.principal)+' &nbsp;&nbsp; <b>Multa:</b> '+money(sec.fine)+' &nbsp;&nbsp; <b>Juros:</b> '+money(sec.interest)+'<div style="font-size:13pt;font-weight:700;margin-top:5px">Subtotal atualizado: '+money(sec.updated)+'</div></div></section>';});
 html+='<section class="report-page" style="page-break-before:always;break-before:page;min-height:950px;padding-top:4px"><div style="font-size:15pt;font-weight:700">ARIANA MÓVEIS</div><div style="font-size:13pt;font-weight:700;margin:0 0 18px">RESUMO GERAL — '+esc(c.name)+'</div><div>Parcelas em aberto: <b>'+totalOpen+'</b></div><div>Parcelas vencidas: <b>'+totalOverdue+'</b></div><div>Principal em aberto: <b>'+money(totalPrincipal)+'</b></div><div>Multa: <b>'+money(totalFine)+'</b></div><div>Juros: <b>'+money(totalInterest)+'</b></div><div style="font-size:16pt;font-weight:700;margin-top:12px">TOTAL ATUALIZADO: '+money(totalUpdated)+'</div></section></div>';return{client:c,text:plain.join('\n'),html};
}
async function openClientReport(key){const base=collectionGroups().find(x=>x.key===key);if(!base)return toast('Cliente não encontrado.');$('client-report-sub').textContent='Montando todas as compras e conferindo o parcelamento original...';$('client-report-text').innerHTML='<div class="empty">Conferindo compras e parcelas do cliente...</div>';openModal('client-report-modal');const r=await clientReportFor(key);if(!r||!r.text){closeModal('client-report-modal');return toast('Este cliente não possui parcelas vencidas ou em aberto.')}window.__clientReportCurrent=r;$('client-report-sub').textContent=r.client.name+' • uma compra por página';$('client-report-text').innerHTML=r.html}
async function copyClientReport(){const r=window.__clientReportCurrent;if(!r?.text)return;try{if(window.ClipboardItem&&navigator.clipboard?.write){const item=new ClipboardItem({'text/html':new Blob([r.html],{type:'text/html'}),'text/plain':new Blob([r.text],{type:'text/plain'})});await navigator.clipboard.write([item])}else await navigator.clipboard.writeText(r.text);toast('Relatório copiado com cada compra separada por página.')}catch{const range=document.createRange();range.selectNodeContents($('client-report-text'));const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);document.execCommand('copy');sel.removeAllRanges();toast('Relatório copiado com cada compra separada.')}}
function printClientReport(){const r=window.__clientReportCurrent;if(!r?.html)return;const w=window.open('','_blank','width=1000,height=900');w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Relatório de contas a receber</title><style>@page{size:A4 portrait;margin:14mm}body{margin:0;color:#172033}.report-page{page-break-after:always;break-after:page}.report-page:last-child{page-break-after:auto;break-after:auto}table{page-break-inside:auto}tr{page-break-inside:avoid;page-break-after:auto}</style></head><body>'+r.html+'<script>window.onload=()=>window.print()<\\/script></body></html>');w.document.close()}
'''
p.write_text(s[:start] + block + s[end:])
